// Rolling-hash substring search; returns first match index or -1.
int rabinKarp(const string& t, const string& p) {
    const long long base = 257, mod = 1e9 + 7;
    int n = t.size(), m = p.size();
    if (m > n) return -1;
    long long ph = 0, wh = 0, power = 1;
    for (int i = 0; i < m; ++i) {
        ph = (ph * base + p[i]) % mod;
        wh = (wh * base + t[i]) % mod;
        if (i) power = power * base % mod;
    }
    for (int i = 0; i + m <= n; ++i) {
        if (wh == ph && t.compare(i, m, p) == 0) return i;       // verify
        if (i + m < n)
            wh = ((wh - t[i] * power % mod + mod) % mod * base + t[i + m]) % mod;
    }
    return -1;
}

def rabin_karp(t, p, base=257, mod=(1<<61)-1):
    n, m = len(t), len(p)
    if m > n: return -1
    ph = wh = 0; power = 1
    for i in range(m):
        ph = (ph*base + ord(p[i])) % mod
        wh = (wh*base + ord(t[i])) % mod
        if i: power = (power*base) % mod
    for i in range(n - m + 1):
        if wh == ph and t[i:i+m] == p:
            return i
        if i < n - m:
            wh = ((wh - ord(t[i])*power) * base + ord(t[i+m])) % mod
    return -1
